using Astrea.BattleActions;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "EffectGainStatusDiceCustomDescription", menuName = "Data/Battle/Battle Actions/BaseBattleActionData/Any/EffectGainStatusDiceCustomDescription", order = 0)]
public class EffectGainStatusDiceCustomDescription : CustomBattleActionDescription
{
	public override string GetActionDescription(string amountModified, BattleAction battleAction)
	{
		EffectGainStatusDiceAction effectGainStatusDiceAction = battleAction as EffectGainStatusDiceAction;
		string actionDescription = effectGainStatusDiceAction.EffectAction.GetActionDescription(effectGainStatusDiceAction.AmountAsStatusDiceAmount ? effectGainStatusDiceAction.EffectAmount : GetAmountWithoutEquation(amountModified));
		HexAction hexAction = effectGainStatusDiceAction.HexAction;
		string text = "";
		text = ((!effectGainStatusDiceAction.OnlyAddIfNoHexDieOnDicePool) ? hexAction.GetActionDescription((!effectGainStatusDiceAction.AmountAsStatusDiceAmount) ? 1 : GetAmountWithoutEquation(amountModified)) : (Smart.Format(base.localizationManager.GetLocalizedString("IfYouHaveNoSpecificDie"), base.localizationManager.GetLocalizedString("Hex_N"), hexAction.GetActionDescription(1).LowercaseFirst()) + "\n"));
		return actionDescription + "\n" + text;
	}
}
